    expect(startOfLocalDay(new Date("2026-03-08T20:00:00.000Z"), "America/New_York")).toBe(
      "2026-03-08T05:00:00.000Z",
    );
    expect(startOfLocalDay(new Date("2026-03-09T20:00:00.000Z"), "America/New_York")).toBe(
      "2026-03-09T04:00:00.000Z",
    );
  });

