    const spring = digestWindow(8, new Date("2026-03-08T18:00:00.000Z"), "America/New_York");
    expect(spring.end).toBe("2026-03-08T12:00:00.000Z");
    expect(spring.start).toBe("2026-03-07T13:00:00.000Z");
    const fall = digestWindow(8, new Date("2026-11-01T18:00:00.000Z"), "America/New_York");
    expect(fall.end).toBe("2026-11-01T13:00:00.000Z");
    expect(fall.start).toBe("2026-10-31T12:00:00.000Z");
    const early = digestWindow(20, new Date("2026-03-15T12:00:00.000Z"), "Asia/Tokyo");
    expect(early.end).toBe("2026-03-15T11:00:00.000Z");
    expect(early.start).toBe("2026-03-14T11:00:00.000Z");
  });
''')
